import{_ as a,o,c as t,ag as d}from"./chunks/framework.DXGyWiRo.js";const m=JSON.parse('{"title":"Field Name Strategy Extensions","description":"","frontmatter":{},"headers":[],"relativePath":"framework/field-name-strategies.md","filePath":"framework/field-name-strategies.md","lastUpdated":1794489741000}'),n={name:"framework/field-name-strategies.md"};function s(i,e,l,c,r,p){return o(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="field-name-strategy-extensions" tabindex="-1">Field Name Strategy Extensions <a class="header-anchor" href="#field-name-strategy-extensions" aria-label="Permalink to &quot;Field Name Strategy Extensions&quot;">​</a></h1><p>EasyYapi ships nine opt-in built-in extensions that normalize every exported field name to a naming convention. They were added in v3.2.7 and all nine are <strong>disabled by default</strong>.</p><h2 id="available-extensions" tabindex="-1">Available Extensions <a class="header-anchor" href="#available-extensions" aria-label="Permalink to &quot;Available Extensions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Extension code</th><th>Rule value</th><th>Example</th></tr></thead><tbody><tr><td><code>field.name.uncapitalize</code></td><td><code>tool.uncapitalize(it.fieldName())</code></td><td><code>Barcode</code> → <code>barcode</code></td></tr><tr><td><code>field.name.capitalize</code></td><td><code>tool.capitalize(it.fieldName())</code></td><td><code>barcode</code> → <code>Barcode</code></td></tr><tr><td><code>field.name.camel-case</code></td><td><code>tool.toCamelCase(it.fieldName())</code></td><td><code>user_name</code> → <code>userName</code></td></tr><tr><td><code>field.name.pascal-case</code></td><td><code>tool.toPascalCase(it.fieldName())</code></td><td><code>user_name</code> → <code>UserName</code></td></tr><tr><td><code>field.name.snake-case</code></td><td><code>tool.toSnakeCase(it.fieldName())</code></td><td><code>URLValue</code> → <code>url_value</code></td></tr><tr><td><code>field.name.kebab-case</code></td><td><code>tool.toKebabCase(it.fieldName())</code></td><td><code>URLValue</code> → <code>url-value</code></td></tr><tr><td><code>field.name.lower-dot-case</code></td><td><code>tool.toLowerDotCase(it.fieldName())</code></td><td><code>URLValue</code> → <code>url.value</code></td></tr><tr><td><code>field.name.upper-snake-case</code></td><td><code>tool.upperCase(tool.toSnakeCase(it.fieldName()))</code></td><td><code>URLValue</code> → <code>URL_VALUE</code></td></tr><tr><td><code>field.name.upper-kebab-case</code></td><td><code>tool.upperCase(tool.toKebabCase(it.fieldName()))</code></td><td><code>URLValue</code> → <code>URL-VALUE</code></td></tr></tbody></table><p>Each extension is a single <code>field.name</code> Groovy rule, so no new rule key, parser, setting, or config syntax is involved.</p><h2 id="enabling-an-extension" tabindex="-1">Enabling an Extension <a class="header-anchor" href="#enabling-an-extension" aria-label="Permalink to &quot;Enabling an Extension&quot;">​</a></h2><p>Enable the one you need in the <strong>Extensions</strong> tab:</p><p><kbd>Settings</kbd> &gt; <kbd>Other Settings</kbd> &gt; <kbd>EasyApi</kbd> &gt; <kbd>Extensions</kbd></p><p>The selection is stored as a comma-separated <code>extensionConfigs</code> value, so it can also be set in a rule file. All nine write the same <code>field.name</code> key — enable <strong>one at a time</strong>.</p><h2 id="acronym-handling" tabindex="-1">Acronym Handling <a class="header-anchor" href="#acronym-handling" aria-label="Permalink to &quot;Acronym Handling&quot;">​</a></h2><p><code>toCamelCase</code>, <code>toSnakeCase</code>, <code>toKebabCase</code>, <code>toPascalCase</code> and <code>toLowerDotCase</code> share one word splitter. Separators (<code>_</code>, <code>-</code>, <code>.</code>, space), camel humps and acronym boundaries are all word boundaries, so <code>URLValue</code> splits into <code>url</code> + <code>value</code>. This is the mainstream boundary used by System.Text.Json, Newtonsoft.Json, Rails, Pydantic, lodash and Jackson&#39;s <code>KebabCaseStrategy</code>.</p><p><code>tool.camel2Underline</code> is the legacy exception: it follows Jackson&#39;s <code>SnakeCaseStrategy</code>, keeps consecutive capitals glued, and turns <code>URLValue</code> into <code>urlvalue</code>. It is kept for existing rules that call it by name; the <code>field.name.snake-case</code> extension uses <code>toSnakeCase</code> instead. See <a href="/settings/tools/tool">tool</a>.</p><p>Bean property names follow <code>java.beans.Introspector.decapitalize</code> since v3.2.7: <code>getURLValue()</code> resolves to <code>URLValue</code> instead of <code>uRLValue</code>. A field and its accessor therefore collide and export as one property — useful for generated models that declare <code>public String Barcode</code> alongside <code>getBarcode()</code>. Enabling <code>field.name.uncapitalize</code> maps both to <code>barcode</code>.</p><h2 id="writing-your-own" tabindex="-1">Writing Your Own <a class="header-anchor" href="#writing-your-own" aria-label="Permalink to &quot;Writing Your Own&quot;">​</a></h2><p>Use the same <code>tool</code> helpers directly in a rule file when the nine presets do not fit:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">field.name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=groovy:```</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    return tool.toSnakeCase(it.fieldName())</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```</span></span></code></pre></div><p>See <a href="/settings/rules/field_name">field.name</a> for the rule and <a href="/settings/tools">Script Tools</a> for the full helper catalog.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="/framework/field-order">Field Order Extensions</a></li><li><a href="/settings/tools/tool">tool</a> — string and case helpers</li></ul>',19)])])}const u=a(n,[["render",s]]);export{m as __pageData,u as default};
